"use client"

import * as React from "react"
import { IconButton } from "@/components/ui/icon-button"
import { Icon } from "@/components/ui/icon-provider"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

type StarButtonProps = Omit<React.ComponentProps<typeof IconButton>, "children" | "onClick" | "aria-pressed" | "aria-label"> & {
  /** Controlled state. Leave it out and the button keeps its own. */
  starred?: boolean
  defaultStarred?: boolean
  onStarredChange?: (starred: boolean) => void
  /** The accessible name; the pressed state says whether it is on. Default "Star". */
  label?: string
  /** Where the Tooltip opens. Default "top". */
  tooltipSide?: "top" | "bottom" | "left" | "right"
}

/**
 * A favourite toggle: an outline star, filled yellow when starred. The Tooltip reads "Star" or "Unstar".
 * A quiet (ghost) Icon Button, so it sits in a header or a row without a frame.
 */
function StarButton({ starred, defaultStarred = false, onStarredChange, label = "Star", tooltipSide = "top", variant = "ghost", size = "sm", className, ...props }: StarButtonProps) {
  const [inner, setInner] = React.useState(defaultStarred)
  const on = starred ?? inner
  const toggle = () => {
    if (starred === undefined) setInner(!on)
    onStarredChange?.(!on)
  }
  return (
    <Tooltip>
      <TooltipTrigger
        describe={false}
        render={
          <IconButton
            data-slot="star-button"
            data-starred={on ? "" : undefined}
            variant={variant}
            size={size}
            aria-label={label}
            aria-pressed={on}
            onClick={toggle}
            className={cn("transition-colors", on && "text-(--yellow-700) [&_svg]:fill-(--yellow-600)", className)}
            {...props}
          />
        }
      >
        <Icon name="star" aria-hidden />
      </TooltipTrigger>
      <TooltipContent side={tooltipSide}>{on ? "Unstar" : "Star"}</TooltipContent>
    </Tooltip>
  )
}

export type { StarButtonProps }
export { StarButton }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip"
import { cn } from "@/lib/utils"

const TooltipContext = React.createContext<{ id: string; open: boolean } | null>(null)

/**
 * Shared delay for a group of tooltips, for example a toolbar: the first tooltip opens after
 * `delay` ms, and moving to the next trigger within `timeout` ms shows its tooltip at once.
 */
function TooltipProvider({ delay = 600, closeDelay = 0, timeout = 300, ...props }: TooltipPrimitive.Provider.Props) {
  return (
    <TooltipPrimitive.Provider delay={delay} closeDelay={closeDelay} timeout={timeout} {...props} />
  )
}

function Tooltip({ defaultOpen, open, onOpenChange, ...props }: TooltipPrimitive.Root.Props) {
  const id = React.useId()
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen ?? false)
  const isOpen = open ?? uncontrolledOpen
  const contextValue = React.useMemo(() => ({ id, open: isOpen }), [id, isOpen])

  return (
    <TooltipContext.Provider value={contextValue}>
      <TooltipPrimitive.Root
        data-slot="tooltip"
        defaultOpen={defaultOpen}
        open={open}
        {...props}
        onOpenChange={(nextOpen, eventDetails) => {
          setUncontrolledOpen(nextOpen)
          onOpenChange?.(nextOpen, eventDetails)
        }}
      />
    </TooltipContext.Provider>
  )
}

function TooltipTrigger({ describe = true, "aria-describedby": ariaDescribedBy, ...props }: TooltipPrimitive.Trigger.Props & { describe?: boolean }) {
  const context = React.useContext(TooltipContext)
  const describedBy = context && describe !== false && context.open
    ? [ariaDescribedBy, context.id].filter(Boolean).join(" ")
    : ariaDescribedBy

  return (
    <TooltipPrimitive.Trigger
      data-slot="tooltip-trigger"
      {...props}
      aria-describedby={describedBy}
    />
  )
}

function TooltipContent({
  className,
  sideOffset = 8,
  children,
  side = "top",
  align,
  anchor,
  shortcut,
  linger = false,
  arrow = true,
  maxWidth = 240,
  ...props
}: TooltipPrimitive.Popup.Props &
  Pick<TooltipPrimitive.Positioner.Props, "sideOffset" | "side" | "align" | "anchor"> & {
    /** Keyboard hint rendered after the label, e.g. "⌘K" (Figma Type=shortcut). */
    shortcut?: string
    /**
     * For confirmations such as "Copied to clipboard": appears at once and,
     * when closed, drifts up slightly while it fades out slowly instead of
     * snapping away.
     */
    linger?: boolean
    /** Show the small point towards the trigger (Figma Show arrow). */
    arrow?: boolean
    /** Widest the label grows before the text wraps onto the next line: 240 px, or 320 px for long translations. */
    maxWidth?: 240 | 320
  }) {
  const context = React.useContext(TooltipContext)
  const maxWidthClass = {
    240: "max-w-60",
    320: "max-w-80",
  } as const

  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Positioner className="isolate z-50 outline-none" sideOffset={sideOffset} side={side} align={align} anchor={anchor}>
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          id={context?.id}
          role="tooltip"
          className={cn(
            // fill-mode-both: the popup is invisible during the enter delay and stays
            // invisible after the exit — without it, it flashes at full opacity at both ends.
            "z-50 inline-flex items-center rounded-md bg-neutral-dark-content px-4 py-2 has-[kbd]:py-[7px] text-xs font-medium text-neutral-white shadow-md fill-mode-both data-open:animate-in data-open:data-instant:animate-none data-closed:data-instant:animate-none data-open:fade-in-0 origin-(--transform-origin) data-open:zoom-in-98 data-open:duration-fast data-open:delay-instant data-open:ease-entrance data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-98 data-closed:duration-instant data-closed:ease-exit",
            maxWidthClass[maxWidth],
            linger &&
              "data-open:delay-0 data-open:slide-in-from-bottom-1 data-closed:zoom-out-100 data-closed:slide-out-to-top-1 data-closed:duration-ambient data-closed:ease-move",
            className
          )}
          {...props}
        >
          {children}
          {shortcut && (
            <kbd className="ms-2 inline-flex h-[18px] items-center rounded-sm bg-bg-tooltip-key px-[5px] font-sans text-xs leading-4 font-semibold text-neutral-white shrink-0 whitespace-nowrap">
              {shortcut}
            </kbd>
          )}
          {/* The arrow points down by default (tooltip above the trigger); when the
              tooltip flips or sits beside the trigger it turns to keep pointing at it. */}
          {arrow && (
            <TooltipPrimitive.Arrow className="data-[side=bottom]:top-[-4px] data-[side=bottom]:rotate-180 data-[side=left]:right-[-6px] data-[side=left]:-rotate-90 data-[side=right]:left-[-6px] data-[side=right]:rotate-90 data-[side=top]:bottom-[-4px]">
              <svg width="10" height="5" viewBox="0 0 10 5" fill="none">
                <path d="M0 0L5 5L10 0Z" className="fill-neutral-dark-content" />
              </svg>
            </TooltipPrimitive.Arrow>
          )}
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  )
}

export { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider }

import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"

// Same states as Button (see button.tsx and the Figma Button / Icon set): the filled variants use fixed
// hover and pressed fills (brand-700/800, red-800/900, dark-400/500, bg-page/bg-subtle on neutral surfaces)
// instead of brightness-95, and focus is the shared 2 px focus-ring (owner rule 31 Oct 2026). The gradient top
// stop is 85 % primary + 15 % brand-500 (4.73:1 with a white icon); hover and pressed step the gradient to
// brand-600/700 and brand-700/800. The light variant's icon is light-1000 (5.93:1 on light-600); it has no
// Figma counterpart, hover and pressed step to the lighter light-500 and light-400 so the icon keeps >= 3:1.
const iconButtonVariants = cva(
  "group/icon-button inline-flex shrink-0 items-center justify-center border border-transparent transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:scale-[0.97] motion-reduce:active:scale-100 disabled:pointer-events-none disabled:opacity-40 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-bg-page data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        primary:
          "border-primary bg-primary text-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:border-(color:--brand-700) hover:bg-(--brand-700) active:border-(color:--brand-800) active:bg-(--brand-800) focus-ring",
        gradient:
          "border-primary bg-gradient-to-b from-[color-mix(in_srgb,var(--primary)_85%,var(--brand-500))] to-primary text-primary-foreground shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05),inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:from-(--brand-600) hover:to-(--brand-700) active:from-(--brand-700) active:to-(--brand-800) focus-ring",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-neutral-white active:bg-(--dark-500) active:text-neutral-white focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-0 focus-visible:outline-(color:--dark-300)",
        light: "bg-(--light-600) text-(--light-1000) hover:bg-(--light-500) data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-(--light-400) focus-ring",
        outline: "bg-card border-primary text-foreground hover:border-tint-text-indigo hover:bg-tint-indigo hover:text-tint-text-indigo data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        // Figma Type=ghost / destructive (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-bg-page data-expanded:bg-bg-subtle data-expanded:hover:bg-bg-subtle active:bg-bg-subtle focus-ring",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:border-(color:--red-800) hover:bg-(color:--red-800) active:border-(color:--red-900) active:bg-(color:--red-900) focus-ring-error",
      },
      shape: {
        rounded: "rounded-md",
        circle: "rounded-full",
      },
      size: {
        sm: "size-8 [&_svg]:size-4",
        md: "size-9 [&_svg]:size-[18px]",
        lg: "size-10 [&_svg]:size-5",
        xl: "size-11 [&_svg]:size-[22px]",
        "2xl": "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

type IconButtonPhase = "idle" | "pending" | "success" | "error"

function IconButton({
  className,
  variant,
  shape,
  size,
  children,
  onClick,
  pending,
  phase,
  expanded,
  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof iconButtonVariants> & {
    /**
     * Shows a spinner in place of the icon, in the same square, and ignores presses.
     * The button stays focusable and keeps its colour (it is not disabled).
     */
    pending?: boolean
    /**
     * Async feedback in the same square: pending shows a spinner, success a check, error a retry icon.
     * The size never changes. The accessible name is yours: change the aria-label with the phase
     * (for example Copy link, Copying, Copied, Retry copying).
     */
    phase?: IconButtonPhase
    /**
     * Marks a trigger whose menu or panel is open: sets aria-expanded and the pressed surface
     * (bg-bg-subtle) on the quiet variants. Leave it undefined when the button does not control a popup.
     */
    expanded?: boolean
  }) {
  const status: IconButtonPhase = phase ?? (pending ? "pending" : "idle")
  const isIdle = status === "idle"

  const resolvedVariant = variant ?? "primary"
  const effectiveVariant =
    status === "error" && ["primary", "brand", "gradient"].includes(resolvedVariant)
      ? "destructive"
      : variant

  const quiet = ["plain", "ghost", "outline"].includes(resolvedVariant)

  let statusIcon: React.ReactNode = null
  if (status === "pending") {
    statusIcon = (
      <Icon name="spinner" aria-hidden className="animate-spin motion-reduce:animate-none" />
    )
  } else if (status === "success") {
    statusIcon = (
      <Icon name="check" aria-hidden strokeWidth={2} className={quiet ? "text-text-success" : undefined} />
    )
  } else if (status === "error") {
    statusIcon = (
      <Icon name="retry" aria-hidden strokeWidth={2} className={quiet ? "text-text-error" : undefined} />
    )
  }

  const handleClick: NonNullable<ButtonPrimitive.Props["onClick"]> = (event) => {
    if (status === "pending") {
      event.preventDefault()
      return
    }
    onClick?.(event)
  }

  return (
    <ButtonPrimitive
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant: isIdle ? variant : effectiveVariant, shape, size, className }))}
      aria-expanded={expanded}
      data-expanded={expanded ? "" : undefined}
      data-phase={isIdle ? undefined : status}
      aria-busy={isIdle ? undefined : status === "pending" ? true : undefined}
      data-pending={isIdle ? undefined : status === "pending" ? "" : undefined}
      onClick={isIdle ? onClick : handleClick}
      {...props}
    >
      {isIdle ? children : statusIcon}
    </ButtonPrimitive>
  )
}

export { IconButton, iconButtonVariants }
export type { IconButtonPhase }
